import {esc,money,stamp,chartHTML} from './charts.js';
const signed=v=>Number.isFinite(v)?`${v>=0?'+':'−'}${money(Math.abs(v))}`:'—';
const percent=v=>Number.isFinite(v)?`${(v*100).toFixed(1)}%`:'—';
const stat=(name,value,note='')=>`<article class="stat"><span class="label">${name}</span><strong>${value}</strong><small>${note}</small></article>`;
export function researchView(feed){
 const r=feed?.research,age=Date.now()-(r?.asOf||0),alive=age>=0&&age<(feed?.transport==='hosted'?90000:10000);
 const connected=feed?.connected&&alive,stale=!alive||r?.valuationStale;
 const series=[{name:'Options research',color:'#65ebc5',points:(r?.history||[]).map(p=>({time:p.time,value:p.equity}))}];
 const reason=!r?feed?.status==='locked'?'Connect your private workspace to view the research account.':'Waiting for the research worker.':!alive?'Research worker offline — last saved results shown.':!feed?.connected?'Cannot connect to Gateway — trading paused.':r.reason;
 const state=connected?(r.pending?'Order pending':r.position?'Position open':'Waiting for setup'):'Paused';
 const plans=r?.plans||[],trades=r?.trades||[];
 return {series,html:`<div class="terminal-summary"><div><span class="eyebrow">OPTIONS RESEARCH · SIMULATED CAD</span><div class="balance-value">${money(r?.equity)}</div><span class="${r?.pnl<0?'negative':'positive'}">${signed(r?.pnl)}</span><span class="dim"> since inception${stale&&r?' · Last known valuation':''}</span></div><div class="engine-state"><span class="badge ${connected&&r?.position?'positive':'warning'}">${state}</span><p>${esc(reason)}</p><small>${r?'Evaluated '+stamp(r.asOf):'Separate CAD $10,000 account'}</small></div></div><div class="stats-row compact-stats">${stat('Cash',money(r?.cash),'CAD')}${stat('Realized P/L',signed(r?.realizedPnl),'After simulated costs')}${stat('Closed trades',r?String(r.closed):'—','One contract per entry')}${stat('Win rate',percent(r?.winRate),'Profitable / all closed trades')}</div><div class="trading-layout"><section class="panel"><div class="panel-head"><h2>Account performance</h2><span class="dim">CAD · recorded equity</span></div>${chartHTML(series,{label:'Options research equity in Canadian dollars'})}<div class="panel-foot">${feed?.transport==='hosted'?'30s relay snapshots':'Local observations'} · Strategy evaluates every second while the Mac is awake.</div></section><aside class="panel"><div class="panel-head"><h2>Position</h2><span class="badge">PAPER</span></div>${r?.position?`<div class="position-ticket"><h3>${esc(r.position.symbol)}</h3><div class="details"><div><span>Quantity</span><strong>1 call · ×100</strong></div><div><span>Entry cost</span><strong>${money(r.position.cost)} CAD</strong></div><div><span>Exit value${stale?' · stale':''}</span><strong>${money(r.position.mark)} CAD</strong></div><div><span>Unrealized P/L</span><strong>${signed(r.position.mark-r.position.cost)}</strong></div><div><span>Target exit</span><strong>${stamp(r.position.dueAt)}</strong></div></div></div>`:'<div class="empty"><span class="empty-icon">⌁</span><h3>No open position</h3><p>Eligible entries and simulated fills will appear here.</p></div>'}<div class="panel-foot">Long calls only · Maximum premium CAD $1,000 · No broker orders</div></aside></div><section class="panel"><div class="panel-head"><h2>Trade plan</h2><span class="dim">5-minute horizon</span></div><div class="table-scroll"><table><thead><tr><th>Contract</th><th>Action</th><th>Projected net P/L · CAD</th><th>Scenario range · CAD</th></tr></thead><tbody>${plans.length?plans.map(p=>`<tr><td><b>${esc(p.symbol)}</b></td><td>${esc(p.reason)}</td><td>${signed(p.expectedPnl)}</td><td>${signed(p.lowPnl)} / ${signed(p.highPnl)}</td></tr>`).join(''):'<tr><td colspan="4">Waiting for a connected option feed.</td></tr>'}</tbody></table></div><details id="research-details" class="disclosure"><summary>Prediction results & strategy</summary><div class="stats-row">${stat('Predicted P/L',signed(r?.predictedPnl),'Matched 5-minute exits')}${stat('Actual P/L',signed(r?.actualMatchedPnl),'Same trades, after costs')}${stat('Direction accuracy',percent(r?.directionAccuracy),`${r?.matched??0} matched exits`)}${stat('Fees paid',money(r?.fees),'CAD · estimated')}</div><p>Rules-based momentum, not a trained AI: 2 minutes of observed live option prices project a 5-minute move. The range is a volatility scenario, not a probability or loss limit. Entry requires a projected edge above CAD $2 after spread, estimated $1 USD commission per side, 0.1% slippage and live USD/CAD conversion.</p><p>One whole call contract at a time. No expiry-day entries. Exit after 5 minutes, at a 10% loss or 15% gain, or before the close; gaps can exceed stops. Pause entries at CAD $300 daily loss or $500 drawdown. A new two-sided quote is required for every fill. Displayed liquidity is not a guarantee of execution.</p></details></section><section class="panel"><div class="panel-head"><h2>Activity</h2><span class="dim">Newest first · simulated fills</span></div><div class="table-scroll"><table><thead><tr><th>Time</th><th>Contract</th><th>Side</th><th>Fill · USD</th><th>Net P/L · CAD</th></tr></thead><tbody>${trades.length?[...trades].reverse().map(t=>`<tr><td>${stamp(t.time)}</td><td>${esc(t.symbol)}</td><td><span class="badge">${esc(t.side)}</span></td><td>${Number(t.price).toFixed(3)}</td><td>${signed(t.pnl)}</td></tr>`).join(''):'<tr><td colspan="5">No fills yet. The engine waits for live quotes and an eligible setup.</td></tr>'}</tbody></table></div></section>`};
}
